select 'transactions' as src, count(*) as n_rows, count(distinct filename) as n_files from read_parquet('s3://bronze/topics/transactions.public.transactions/event_date=*/*.parquet', hive_partitioning=true, union_by_name=true, filename=true) union all select 'ledger_entries', count(*), count(distinct filename) from read_parquet('s3://bronze/topics/transactions.public.ledger_entries/event_date=*/*.parquet', filename=true) union all select 'accounts', count(*), count(distinct filename) from read_parquet('s3://bronze/topics/transactions.public.accounts/event_date=*/*.parquet', filename=true)